<script>document.addEventListener('DOMContentLoaded',function(){['supplier','orderNote','documentScope'].forEach(function(id){var select=document.getElementById(id);if(!select)return;if(window.Choices)new Choices(select,{searchEnabled:id!=='documentScope',shouldSort:false,itemSelectText:'',searchPlaceholderValue:'Search...'});select.addEventListener('change',function(){if(id==='supplier'){document.getElementById('documentScope').value='open';}if(id==='orderNote'&&select.value==='__new__'){var create=function(reference){if(!reference)return;var form=document.createElement('form');form.method='POST';form.action='{{ route('erp.oms.order_notes.store') }}';[[' _token','{{ csrf_token() }}'],['supplier_id','{{ $selectedSupplierId }}'],['reference',reference],['return_to','simple']].forEach(function(field){var input=document.createElement('input');input.type='hidden';input.name=field[0].trim();input.value=field[1];form.appendChild(input)});document.body.appendChild(form);form.submit()};if(window.Swal){Swal.fire({title:'Create order note',input:'text',inputLabel:'Order note name',showCancelButton:true,confirmButtonText:'Create'}).then(function(result){if(result.isConfirmed)create(result.value)})}else{create(window.prompt('Order note name'))}return}select.form.submit()})});document.querySelectorAll('.js-backorders').forEach(function(button){button.addEventListener('click',function(){var orders=JSON.parse(button.dataset.orders);if(orders.length===1){window.open(orders[0].url,'_blank');return}document.querySelector('#backordersRows').innerHTML=orders.map(function(order){return '<tr><td><a target="_blank" href="'+order.url+'">'+order.id_order+'</a></td><td>'+order.reference+'</td><td>'+order.store+'</td><td>'+order.stock+'</td></tr>'}).join('');bootstrap.Modal.getOrCreateInstance('#backordersModal').show()})})})</script>
<script>document.addEventListener('DOMContentLoaded',function(){var row=document.getElementById('addOrderLine');if(!row)return;var search=document.getElementById('newProductSearch'),suggestions=document.getElementById('newProductSuggestions'),productId=document.getElementById('newProductId'),attributeId=document.getElementById('newProductAttributeId'),qty=document.getElementById('newProductQty'),purchase=document.getElementById('newPurchasePrice'),sale=document.getElementById('newSalePrice'),purchaseEur=document.getElementById('newPurchaseEur'),saleEur=document.getElementById('newSaleEur'),barcodeCell=document.getElementById('newBarcodeCell'),stockCell=document.getElementById('newStockCell'),button=document.getElementById('addOrderLineButton'),timer,items=[];var message=function(text){if(window.Swal){Swal.fire({icon:'error',text:text})}else{window.alert(text)}};var selectProduct=function(item){productId.value=item.product_id;attributeId.value=item.product_attribute_id||'';search.value=item.sku||'';purchase.value=Number(item.purchase_supplier||0).toFixed(2);sale.value=Number(item.sale_supplier||0).toFixed(2);purchaseEur.textContent='\u20ac '+Number(item.purchase_eur||0).toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2});saleEur.textContent='\u20ac '+Number(item.sale_eur||0).toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2});barcodeCell.innerHTML=item.barcode?'<button type="button" class="barcode-button" title="'+item.barcode+'"><i class="fa-solid fa-barcode"></i></button>':'';var stock=Number(item.stock_qty||0),stockClass=stock>1?'stock-high':(stock===1?'stock-one':'stock-low');stockCell.innerHTML='<span class="stock-badge '+stockClass+'">'+stock+'</span>';suggestions.innerHTML='';suggestions.classList.add('d-none');qty.focus();qty.select()};var selectMatching=function(){var item=items.find(function(candidate){return candidate.label===search.value});if(item)selectProduct(item)};search.addEventListener('input',function(){productId.value='';attributeId.value='';purchase.value='';sale.value='';purchaseEur.textContent='';saleEur.textContent='';barcodeCell.innerHTML='';stockCell.innerHTML='';clearTimeout(timer);var query=search.value.trim();if(query.length<2){suggestions.innerHTML='';items=[];return}timer=setTimeout(function(){fetch(row.dataset.search+'?q='+encodeURIComponent(query),{headers:{Accept:'application/json'},credentials:'same-origin'}).then(function(response){if(!response.ok)throw new Error('Unable to search products.');return response.json()}).then(function(payload){items=(payload.items||[]).map(function(item){item.label=(item.sku||'')+' - '+(item.display_name||'');return item});suggestions.innerHTML='';items.forEach(function(item){var option=document.createElement('button');option.type='button';option.className='product-suggestion';var child=document.createElement('span');child.className='child-ref';child.textContent=item.sku||'';option.appendChild(child);if(item.product_attribute_id&&item.parent_reference&&item.parent_reference!==item.sku){var separator=document.createElement('span');separator.textContent=' | ';option.appendChild(separator);var parent=document.createElement('span');parent.className='parent-ref';parent.textContent=item.parent_reference;option.appendChild(parent)}var displayName=item.display_name||'';if(displayName&&displayName!==item.parent_reference&&displayName!==item.sku){var name=document.createElement('span');name.textContent=' - '+displayName;option.appendChild(name)}option.addEventListener('click',function(){selectProduct(item)});suggestions.appendChild(option)});suggestions.classList.toggle('d-none',items.length===0)}).catch(function(error){items=[];suggestions.innerHTML='';message(error.message)})},220)});search.addEventListener('change',selectMatching);search.addEventListener('keydown',function(event){if(event.key==='Enter'){event.preventDefault();selectMatching();if(productId.value)qty.focus()}});button.addEventListener('click',function(){selectMatching();if(!productId.value){message('Select a product from the suggestions first.');search.focus();return}if(Number(qty.value)<1){message('Quantity must be at least 1.');qty.focus();return}button.disabled=true;var token=document.querySelector('input[name="_token"]');var body=new URLSearchParams({product_id:productId.value,product_attribute_id:attributeId.value,qty_ordered:qty.value,_token:token?token.value:''});fetch(row.dataset.store,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:body.toString()}).then(function(response){return response.json().then(function(payload){if(!response.ok)throw new Error(payload.message||'Unable to add product.');return payload})}).then(function(){window.location.reload()}).catch(function(error){button.disabled=false;message(error.message)})})})</script>
