<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.js-barcode').forEach(function(button){button.addEventListener('click',function(){var barcode=button.dataset.barcode||'';if(!barcode||!window.JsBarcode)return;var popup=window.open('','_blank','width=520,height=260');if(!popup){window.alert('Allow pop-ups to print the barcode.');return}var svg=document.createElementNS('http://www.w3.org/2000/svg','svg');try{JsBarcode(svg,barcode,{format:'CODE128',displayValue:true,fontSize:18,margin:16,width:2,height:90});popup.document.write('<!doctype html><html><head><title>Barcode</title><style>body{margin:0;display:grid;min-height:100vh;place-items:center;font-family:Arial}svg{max-width:95vw}</style></head><body>'+svg.outerHTML+'<script>window.onload=function(){window.print()}<\/script></body></html>');popup.document.close()}catch(error){popup.close();window.alert('Unable to generate this barcode.')}})})})</script><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.product-image-toggle').forEach(function(b){b.addEventListener('click',function(){document.getElementById(b.dataset.target).classList.toggle('d-none')})})})</script><script>document.addEventListener('DOMContentLoaded',function(){var filter=document.getElementById('orderLineFilter');if(filter){filter.addEventListener('input',function(){var q=this.value.toLowerCase().trim();document.querySelectorAll('.oms-product-row').forEach(function(row){var visible=!q||row.dataset.filter.indexOf(q)!==-1;row.style.display=visible?'':'none';var detail=document.getElementById('productDetail'+row.querySelector('input[name*="order_note_line_id"]').value);if(detail&&!visible)detail.classList.add('d-none')})})}document.querySelectorAll('.js-currency-price').forEach(function(input){input.addEventListener('input',function(){var rate=Number(input.dataset.eurRate)||1,value=Number(input.value)||0,eur=input.closest('.price').querySelector('.eur');if(eur)eur.textContent='€ '+(value/rate).toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})})});document.querySelectorAll('.js-product-meta').forEach(function(input){input.addEventListener('change',function(){var token=document.querySelector('input[name="_token"]'),body=new URLSearchParams({_token:token?token.value:'',_method:'PATCH'});body.append(input.dataset.field,input.value);fetch(input.closest('.product-detail-row').dataset.metaUrl,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:body.toString()}).then(function(r){if(!r.ok)throw new Error('Unable to save product information.');input.classList.remove('is-invalid');input.classList.add('is-valid')}).catch(function(){input.classList.add('is-invalid')})})});document.querySelectorAll('.js-remove-line').forEach(function(button){button.addEventListener('click',function(){var remove=function(){fetch(button.dataset.url,{method:'DELETE',headers:{'X-CSRF-TOKEN':document.querySelector('input[name="_token"]').value,Accept:'application/json'},credentials:'same-origin'}).then(function(r){if(!r.ok)throw new Error('Unable to remove line.');window.location.reload()}).catch(function(e){window.Swal?Swal.fire({icon:'error',text:e.message}):alert(e.message)})};if(window.Swal){Swal.fire({icon:'warning',title:'Remove this line?',text:'This operation is irreversible and updates arrived quantity and stock when applicable.',showCancelButton:true,confirmButtonText:'Remove'}).then(function(r){if(r.isConfirmed)remove()})}else if(confirm('Remove this line?'))remove()})})})</script><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.js-remove-order').forEach(function(button){button.addEventListener('click',function(){if(!confirm('Remove this order note and all its lines? This is irreversible.'))return;var token=document.querySelector('input[name="_token"]');fetch(button.dataset.url,{method:'DELETE',headers:{'X-CSRF-TOKEN':token?token.value:'',Accept:'application/json'},credentials:'same-origin'}).then(function(response){if(!response.ok)throw new Error();window.location.href='/customTools/erp/oms/simple'}).catch(function(){alert('Unable to remove order note.')})})})})</script><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.js-order-qty').forEach(function(input){input.addEventListener('change',function(){var value=input.value.trim(),token=document.querySelector('input[name="_token"]');if(!/^\d+$/.test(value)){input.classList.add('is-invalid');return}input.disabled=true;var body=new URLSearchParams({_token:token?token.value:'',_method:'PATCH',qty_ordered:value});fetch(input.dataset.url,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:body.toString()}).then(function(response){return response.json().then(function(payload){if(!response.ok)throw new Error(payload.message||'Unable to update ordered quantity.');return payload})}).then(function(){window.location.reload()}).catch(function(error){input.disabled=false;input.classList.add('is-invalid');window.Swal?Swal.fire({icon:'error',text:error.message}):alert(error.message)})})})})</script><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.js-received-qty[data-url]').forEach(function(input){input.addEventListener('change',function(){var value=input.value.trim(),token=document.querySelector('input[name="_token"]');if(!/^\d+$/.test(value)){input.classList.add('is-invalid');return}if(!confirm('Update received quantity? Stock, stock arrive and history will be updated.'))return;input.disabled=true;fetch(input.dataset.url,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:new URLSearchParams({_token:token?token.value:'',_method:'PATCH',qty_received:value}).toString()}).then(function(r){if(!r.ok)th