', '));var item=invoices.find(function(entry){return String(entry.id)===String(selected)});if(item)apply(item)}})})})</script><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.js-add-to-invoice').forEach(function(input){input.addEventListener('change',function(){var qty=Number(input.value),row=input.closest('tr'),invoice=document.getElementById('workingInvoice'),line=row.querySelector('.js-order-note-line'),token=document.querySelector('input[name="_token"]');if(!Number.isInteger(qty)||qty<0)return;if(!qty)return;if(!invoice.value){alert('Select an open invoice first.');input.value=0;return}var purchase=row.querySelector('input[name$="[unit_price]"]'),sale=row.querySelector('input[name$="[sale_price]"]'),body=new URLSearchParams({_token:token?token.value:'',existing_invoice_id:invoice.value,invoice_action:'save_draft','lines[0][order_note_line_id]':line.value,'lines[0][qty_billed]':qty,'lines[0][unit_price]':purchase?purchase.value:0,'lines[0][sale_price]':sale?sale.value:0});input.disabled=true;fetch('{{ route('erp.oms.invoices.store', $orderNote) }}',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:body.toString()}).then(function(r){if(!r.ok)throw new Error('Unable to add this line to the selected invoice.');window.location.reload()}).catch(function(e){input.disabled=false;alert(e.message)})})})})</script>@endsection
